package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.indexOfAny(CharSequence cs, char[] searchChars)
 */
public class StringUtils_indexOfAny_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(null, new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_EmptyCharSequence() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", new char[]{'a'}));
    }

    @Test
    public void testIndexOfAny_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchChars() {
        // Assuming ArrayUtils.isEmpty returns true for empty array
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new char[]{}));
    }

    @Test
    public void testIndexOfAny_FoundAtStart() {
        assertEquals(0, StringUtils.indexOfAny("abcde", new char[]{'a', 'z'}));
    }

    @Test
    public void testIndexOfAny_FoundInMiddle() {
        assertEquals(2, StringUtils.indexOfAny("abcde", new char[]{'c', 'z'}));
    }

    @Test
    public void testIndexOfAny_FoundAtEnd() {
        assertEquals(4, StringUtils.indexOfAny("abcde", new char[]{'e', 'z'}));
    }

    @Test
    public void testIndexOfAny_NotFound() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abcde", new char[]{'x', 'y'}));
    }

    @Test
    public void testIndexOfAny_SingleCharSearch() {
        assertEquals(1, StringUtils.indexOfAny("abc", new char[]{'b'}));
    }

    /**
     * Testing the supplementary character logic (High Surrogate handling).
     * The code checks if the character is a high surrogate and verifies if the 
     * subsequent character in the search array matches the subsequent character in the string.
     */
    @Test
    public void testIndexOfAny_SupplementaryCharacter_Match() {
        // U+1F600 (Grinning Face) is represented by \uD83D\uDE00
        String emoji = "\uD83D\uDE00"; 
        char[] searchChars = new char[]{\uD83D, \uDE00};

        // This tests the branch: if (i < csLast && j < searchLast && Character.isHighSurrogate(ch))
        // and the inner if: if (searchChars[j + 1] == cs.charAt(i + 1))
        assertEquals(0, StringUtils.indexOfAny(emoji, searchChars));
    }

    @Test
    public void testIndexOfAny_SupplementaryCharacter_PartialMatchFail() {
        // String has the high surrogate, but searchChars only has the high surrogate 
        // or the wrong low surrogate.
        String emoji = "\uD83D\uDE00";
        char[] searchChars = new char[]{\uD83D, \uDE01}; // Different low surrogate

        // The loop will check searchChars[0] == emoji.charAt(0) -> true
        // Then check if (0 < 1 && 0 < 1 && isHighSurrogate) -> true
        // Then check if (searchChars[1] == emoji.charAt(1)) -> false
        // The loop continues.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny(emoji, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogateAtEndOfCS() {
        // If the high surrogate is the last character of the string, 
        // it cannot be part of a valid supplementary pair in this context.
        String cs = "\uD83D";
        char[] searchChars = new char[]{\uD83D};
        assertEquals(0, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_HighSurrogateAtEndOfSearchChars() {
        // If the high surrogate is the last character of the searchChars array,
        // it falls into the 'else' branch of the surrogate check.
        String cs = "\uD83D\uDE00";
        char[] searchChars = new char[]{'a', \uD83D};
        // Even though \uD83D is in the string, the searchChar index j is searchLast,
        // so it should trigger the 'else' branch and return the index.
        assertEquals(0, StringUtils.indexOfAny(cs, searchChars));
    }

    @Test
    public void testIndexOfAny_MultipleMatches() {
        // Should return the first occurrence
        assertEquals(0, StringUtils.indexOfAny("banana", new char[]{'a', 'b'}));
    }
}
